import 'dart:convert';
import 'dart:io';

import 'package:content_build/content_build.dart';
import 'package:test/test.dart';

/// The fixture generated by this tool from the downloaded canon. Re-generate
/// with `--fixture-out`, never edit by hand.
const String fixturePath =
    '../../packages/testing/fixtures/content_p582_583.json';

const String configPath = 'config/prototype.json';

void main() {
  late Map<String, Object?> fixture;
  late List<Map<String, Object?>> words;
  late List<Map<String, Object?>> ayahs;

  List<Map<String, Object?>> rows(String table) =>
      (fixture[table]! as List<Object?>).cast<Map<String, Object?>>();
  // Every table key is written by ContentData.toJson.

  setUpAll(() {
    fixture = jsonDecode(File(fixturePath).readAsStringSync())
        as Map<String, Object?>;
    words = rows('words');
    ayahs = rows('ayahs');
  });

  test('was built from the pinned canon with a license (ПР-02, ПР-04)', () {
    final config = BuildConfig.fromJson(File(configPath).readAsStringSync());
    final version = (fixture['contentVersion']! as Map<String, Object?>)
        .cast<String, String>(); // Always written.
    expect(version['canonSha256'], config.expectedCanonSha256);
    expect(version['textLicense'], config.text.license);
    expect(version['textNotice'], contains('Tanzil'));
  });

  test('surah 78 is complete: 40 ayahs, word counts match rows', () {
    final surah78 = ayahs.where((a) => a['surah'] == 78).toList();
    expect(surah78, hasLength(40));
    for (final ayah in ayahs) {
      final count = words
          .where(
            (w) => w['surah'] == ayah['surah'] && w['ayah'] == ayah['ayah'],
          )
          .length;
      expect(
        count,
        ayah['wordCount'],
        reason: '${ayah['surah']}:${ayah['ayah']}',
      );
    }
  });

  test('every word has a page, a line and a glyph code (ПР-04)', () {
    for (final w in words) {
      final where = '${w['surah']}:${w['ayah']}:${w['position']}';
      expect([582, 583], contains(w['page']), reason: where);
      expect(w['line'], inInclusiveRange(1, 15), reason: where);
      expect(w['glyphCode'], isA<String>(), reason: where);
      expect(w['glyphCode'], isNotEmpty, reason: where);
    }
  });

  test('word indexes are contiguous and words are canon slices', () {
    final indexes = [for (final w in words) w['wordIndex']! as int];
    for (var i = 1; i < indexes.length; i++) {
      expect(indexes[i], indexes[i - 1] + 1);
    }
    for (final ayah in ayahs) {
      final texts = [
        for (final w in words)
          if (w['surah'] == ayah['surah'] && w['ayah'] == ayah['ayah'])
            w['textUthmani']! as String,
      ];
      expect(segmentAyah(texts.join(tanzilTokenSeparator)), texts);
    }
  });
}
